import React, { useEffect, useState } from 'react';

const LEAF_EMOJIS = ['🍃', '🌿', '🍀', '🌱', '🌾'];

const SplashScreen = ({ onDone }) => {
  const [leaves] = useState(() =>
    Array.from({ length: 14 }, (_, i) => ({
      id: i,
      left: Math.random() * 100,
      delay: Math.random() * 3,
      duration: 2 + Math.random() * 2,
      emoji: LEAF_EMOJIS[Math.floor(Math.random() * LEAF_EMOJIS.length)],
      size: 16 + Math.random() * 16
    }))
  );

  useEffect(() => {
    const timer = setTimeout(onDone, 2800);
    return () => clearTimeout(timer);
  }, [onDone]);

  return (
    <div className="splash-screen">
      {leaves.map(leaf => (
        <div
          key={leaf.id}
          className="leaf-fall"
          style={{
            left: `${leaf.left}%`,
            animationDelay: `${leaf.delay}s`,
            animationDuration: `${leaf.duration}s`,
            fontSize: `${leaf.size}px`
          }}
        >
          {leaf.emoji}
        </div>
      ))}
      <div className="splash-logo-container">
        <div className="splash-logo-icon">🌱</div>
        <div className="splash-title">ECOISTIC</div>
        <div className="splash-subtitle">FRIENDLY</div>
        <div style={{ marginTop: 20, color: '#a5d6a7', fontSize: '0.8rem', letterSpacing: 2 }}>
          GROW GREEN TOGETHER
        </div>
      </div>
    </div>
  );
};

export default SplashScreen;
